# Inventory list filters: enforce <=100 rows and support server-side category/unassigned filters.
Path("server/routes/inventory/inventoryRequestContext.ts").write_text('''import type { Request } from "express";\n\nimport { InventoryRouteError } from "./inventoryErrors";\n\nexport interface InventoryListFilters {\n  page: number;\n  pageSize: number;\n  search?: string;\n  locationId?: number;\n  stockGroupId?: number;\n  unassignedStockGroup?: boolean;\n  categoryIds?: number[];\n  includeUncategorized?: boolean;\n  profile?: string;\n}\n\nexport interface QuickAdjustmentInput {\n  stockItemId: number;\n  locationId: number;\n  quantity: number;\n  type: "add" | "subtract";\n}\n\nexport interface InventoryAuditActor {\n  userId: string;\n  username: string;\n}\n\nexport function getActiveInventoryCompanyId(req: Request): number {\n  const companyId = Number(req.session?.currentCompanyId);\n  if (!Number.isInteger(companyId) || companyId <= 0) {\n    throw new InventoryRouteError(400, "No company selected");\n  }\n  return companyId;\n}\n\nexport function parseInventoryListFilters(req: Request): InventoryListFilters {\n  const page = Math.max(1, Number.parseInt(String(req.query.page || "1"), 10) || 1);\n  const pageSize = Math.min(100, Math.max(1, Number.parseInt(String(req.query.pageSize || "50"), 10) || 50));\n  const search =\n    typeof req.query.search === "string" && req.query.search.trim()\n      ? req.query.search.trim().slice(0, 100)\n      : undefined;\n  const locationId = req.query.locationId ? Number.parseInt(String(req.query.locationId), 10) : undefined;\n\n  const stockGroupRaw = String(req.query.stockGroupId ?? "");\n  const unassignedStockGroup = stockGroupRaw === "none" || stockGroupRaw === "null";\n  const stockGroupId = /^\\d+$/.test(stockGroupRaw) ? Number.parseInt(stockGroupRaw, 10) : undefined;\n\n  const categoryParts = String(req.query.categoryIds ?? req.query.categoryId ?? "")\n    .split(",")\n    .map((part) => part.trim())\n    .filter(Boolean);\n  const includeUncategorized = categoryParts.includes("none") || categoryParts.includes("null");\n  const categoryIds = Array.from(\n    new Set(categoryParts.filter((part) => /^\\d+$/.test(part)).map((part) => Number.parseInt(part, 10)))\n  ).slice(0, 50);\n\n  const profile = typeof req.query.profile === "string" ? req.query.profile : undefined;\n  return {\n    page,\n    pageSize,\n    search,\n    locationId,\n    stockGroupId,\n    unassignedStockGroup,\n    categoryIds: categoryIds.length > 0 ? categoryIds : undefined,\n    includeUncategorized,\n    profile,\n  };\n}\n\nexport function parseQuickAdjustmentInput(input: unknown): QuickAdjustmentInput {\n  const body = input && typeof input === "object" ? (input as Record<string, unknown>) : {};\n  const { stockItemId, locationId, quantity, type } = body;\n  if (!stockItemId || !locationId || !quantity || !type) {\n    throw new InventoryRouteError(400, "Missing required fields: stockItemId, locationId, quantity, type");\n  }\n\n  const parsedStockItemId = Number(stockItemId);\n  const parsedLocationId = Number(locationId);\n  const parsedQuantity = Number.parseFloat(String(quantity));\n  if (!Number.isInteger(parsedStockItemId) || parsedStockItemId <= 0) {\n    throw new InventoryRouteError(400, "Invalid stock item ID");\n  }\n  if (!Number.isInteger(parsedLocationId) || parsedLocationId <= 0) {\n    throw new InventoryRouteError(400, "Invalid location ID");\n  }\n  if (!Number.isFinite(parsedQuantity) || parsedQuantity <= 0) {\n    throw new InventoryRouteError(400, "Quantity must be a positive number");\n  }\n  if (type !== "add" && type !== "subtract") {\n    throw new InventoryRouteError(400, "Type must be 'add' or 'subtract'");\n  }\n\n  return {\n    stockItemId: parsedStockItemId,\n    locationId: parsedLocationId,\n    quantity: parsedQuantity,\n    type,\n  };\n}\n\nexport function getInventoryAuditActor(req: Request): InventoryAuditActor {\n  return {\n    userId: req.session.userId!,\n    username: req.session.username || "unknown",\n  };\n}\n''')

Path("server/routes/inventory/inventoryQueryService.ts").write_text('''import { and, asc, eq, ilike, inArray, isNull, or, sql } from "drizzle-orm";\nimport { inventory, locations, stockCategories, stockGroups, stockItems } from "@shared/schema";\n\nimport { db } from "../../db";\nimport type { InventoryListFilters } from "./inventoryRequestContext";\n\nfunction buildInventoryConditions(companyId: number, filters: InventoryListFilters) {\n  const conditions: any[] = [\n    eq(inventory.companyId, companyId),\n    isNull(locations.deletedAt),\n    isNull(stockItems.deletedAt),\n  ];\n  if (filters.locationId) conditions.push(eq(inventory.locationId, filters.locationId));\n  if (filters.unassignedStockGroup) conditions.push(isNull(stockItems.stockGroupId));\n  else if (filters.stockGroupId) conditions.push(eq(stockItems.stockGroupId, filters.stockGroupId));\n\n  if (filters.categoryIds?.length || filters.includeUncategorized) {\n    const categoryConditions: any[] = [];\n    if (filters.categoryIds?.length) categoryConditions.push(inArray(stockItems.categoryId, filters.categoryIds));\n    if (filters.includeUncategorized) categoryConditions.push(isNull(stockItems.categoryId));\n    conditions.push(or(...categoryConditions));\n  }\n\n  if (filters.search) {\n    const query = `%${filters.search}%`;\n    conditions.push(\n      or(\n        ilike(stockItems.name, query),\n        ilike(stockItems.code, query),\n        ilike(stockGroups.name, query),\n        ilike(stockCategories.name, query)\n      )\n    );\n  }\n  return and(...conditions);\n}\n\nexport async function getInventoryPage(companyId: number, filters: InventoryListFilters) {\n  const where = buildInventoryConditions(companyId, filters);\n  const offset = (filters.page - 1) * filters.pageSize;\n\n  if (filters.profile === "combined") {\n    const [{ total }] = await db\n      .select({ total: sql<number>`count(DISTINCT ${inventory.stockItemId})::int` })\n      .from(inventory)\n      .leftJoin(stockItems, eq(inventory.stockItemId, stockItems.id))\n      .leftJoin(stockGroups, eq(stockItems.stockGroupId, stockGroups.id))\n      .leftJoin(stockCategories, eq(stockItems.categoryId, stockCategories.id))\n      .innerJoin(locations, eq(inventory.locationId, locations.id))\n      .where(where);\n\n    const data = await db\n      .select({\n        stockItemId: inventory.stockItemId,\n        stockItemName: sql<string>`COALESCE(${stockItems.name}, '')`,\n        stockItemCode: sql<string>`COALESCE(${stockItems.code}, '')`,\n        totalQty: sql<string>`COALESCE(SUM(${inventory.quantity}::numeric), 0)::text`,\n        avgCost: sql<string>`CASE\n          WHEN COALESCE(SUM(${inventory.quantity}::numeric), 0) = 0 THEN '0'\n          ELSE (COALESCE(SUM(${inventory.totalValue}::numeric), 0) / NULLIF(SUM(${inventory.quantity}::numeric), 0))::text\n        END`,\n        totalValue: sql<string>`COALESCE(SUM(${inventory.totalValue}::numeric), 0)::text`,\n        stockGroupId: stockItems.stockGroupId,\n        stockGroupName: sql<string>`COALESCE(${stockGroups.name}, 'Unassigned')`,\n        categoryId: stockItems.categoryId,\n        categoryName: stockCategories.name,\n        qtyByLocationName: sql<Record<string, string>>`COALESCE(\n          jsonb_object_agg(${locations.name}, ${inventory.quantity})\n            FILTER (WHERE ${locations.name} IS NOT NULL),\n          '{}'::jsonb\n        )`,\n      })\n      .from(inventory)\n      .leftJoin(stockItems, eq(inventory.stockItemId, stockItems.id))\n      .leftJoin(stockGroups, eq(stockItems.stockGroupId, stockGroups.id))\n      .leftJoin(stockCategories, eq(stockItems.categoryId, stockCategories.id))\n      .innerJoin(locations, eq(inventory.locationId, locations.id))\n      .where(where)\n      .groupBy(\n        inventory.stockItemId,\n        stockItems.name,\n        stockItems.code,\n        stockItems.stockGroupId,\n        stockGroups.name,\n        stockItems.categoryId,\n        stockCategories.name\n      )\n      .orderBy(asc(stockGroups.name), asc(stockItems.name))\n      .limit(filters.pageSize)\n      .offset(offset);\n\n    return {\n      data,\n      page: filters.page,\n      pageSize: filters.pageSize,\n      total,\n      totalPages: Math.ceil(total / filters.pageSize),\n    };\n  }\n\n  const [{ total }] = await db\n    .select({ total: sql<number>`count(*)::int` })\n    .from(inventory)\n    .leftJoin(stockItems, eq(inventory.stockItemId, stockItems.id))\n    .leftJoin(stockGroups, eq(stockItems.stockGroupId, stockGroups.id))\n    .leftJoin(stockCategories, eq(stockItems.categoryId, stockCategories.id))\n    .innerJoin(locations, eq(inventory.locationId, locations.id))\n    .where(where);\n\n  const data = await db\n    .select({\n      inventoryId: inventory.id,\n      locationId: inventory.locationId,\n      locationName: locations.name,\n      locationCode: locations.code,\n      stockItemId: inventory.stockItemId,\n      quantity: inventory.quantity,\n      averageRate: inventory.averageRate,\n      totalValue: inventory.totalValue,\n      stockItemCode: stockItems.code,\n      stockItemName: stockItems.name,\n      stockItemUom: stockItems.uom,\n      stockGroupId: stockItems.stockGroupId,\n      stockGroupName: sql<string>`COALESCE(${stockGroups.name}, '')`,\n      stockGroupCode: sql<string>`COALESCE(${stockGroups.code}, '')`,\n      categoryId: stockItems.categoryId,\n      categoryName: stockCategories.name,\n    })\n    .from(inventory)\n    .leftJoin(stockItems, eq(inventory.stockItemId, stockItems.id))\n    .leftJoin(stockGroups, eq(stockItems.stockGroupId, stockGroups.id))\n    .leftJoin(stockCategories, eq(stockItems.categoryId, stockCategories.id))\n    .innerJoin(locations, eq(inventory.locationId, locations.id))\n    .where(where)\n    .orderBy(asc(stockItems.code), asc(locations.name))\n    .limit(filters.pageSize)\n    .offset(offset);\n\n  return {\n    data,\n    page: filters.page,\n    pageSize: filters.pageSize,\n    total,\n    totalPages: Math.ceil(total / filters.pageSize),\n  };\n}\n''')

