old_stock_query = '''  const { data: stockItems = [] } = useQuery<StockItem[]>({\n    queryKey: ["/api/stock-items/light", selectedCompany?.id],\n    staleTime: 5 * 60 * 1000,\n    refetchOnWindowFocus: false,\n    refetchOnReconnect: false,\n  });\n'''
